const allRows = $input.all();
const results = [];
const staticData = $getWorkflowStaticData('global');

for (const item of allRows) {
  const rowData = item.json;

  // Skip row if already processed (has status or ticket_id)
  if (rowData.status && rowData.status.trim() !== '') {
    continue;
  }
  if (rowData.ticket_id && rowData.ticket_id.trim() !== '') {
    continue;
  }

  // Generate unique ticket_id using timestamp + random string
  const timestamp = Date.now();
  const random = Math.random().toString(36).substring(2, 8);
  const ticket_id = `TKT_${timestamp}_${random}`;

  // Track which product is currently presented to admins for vote
  staticData.lastPresentedTicketId = ticket_id;

  results.push({
    json: {
      ...rowData,
      ticket_id: ticket_id,
      status: 'EN_ATTENTE',
      phone_number: rowData.phone_number || '',
      client_name: rowData.Name || rowData.client_name || 'Unknown'
    }
  });
}

return results;

