}

const triggerData = $('Classify Message').first().json;

// PRIMARY: use _replyText already cleaned by Classify Message
let replyText = triggerData._replyText || '';
let senderPhone = '';

try {
  if (triggerData.entry) {
    const messages = triggerData.entry[0]?.changes?.[0]?.value?.messages;
    if (messages && messages.length > 0) {
      senderPhone = messages[0].from || '';
    }
  } else if (triggerData.messages) {
    senderPhone = triggerData.messages[0]?.from || '';
  }
} catch (e) { /* ignore */ }

replyText = cleanText(replyText);

// IMPORTANT: Skip messages starting with 'vo' - those are for Voice Over flow
if (replyText.startsWith('vo ') || replyText === 'vo') {
  return [];
}

// IMPORTANT: Skip messages starting with 'mt' - those are for Montage flow
if (replyText.startsWith('mt ') || replyText === 'mt') {
  return [];
}

// Analyze reply for confirmation or cancellation
let action = 'none';
const confirmWords = ['oui', 'ok', 'yes', 'confirm', 'confirmer', '1'];
const cancelWords = ['non', 'no', 'cancel', 'annuler', '2'];

if (confirmWords.some(word => replyText.includes(word))) {
  action = 'confirm';
} else if (cancelWords.some(word => replyText.includes(word))) {
  action = 'cancel';
}

// Only process the FIRST pending row (oldest one)
const rows = $input.all();

if (action === 'none') {
  return [];
}

// Check static data for late-voter detection
const staticData = $getWorkflowStaticData('global');
const lastPresentedTicketId = staticData.lastPresentedTicketId || '';
const lastProcessedAction = staticData.lastProcessedAction || '';
const lastProcessedProductName = staticData.lastProcessedProductName || '';

if (rows.length === 0) {
  // No more pending products - admin voted after queue is empty
  return [{
    json: {
      action: 'no_pending',
      senderPhone: senderPhone,
      lastProcessedAction: lastProcessedAction,
      lastProcessedProductName: lastProcessedProductName,
      hasNextProduct: false,
      nextProduct: null
    }
  }];
}

const firstRow = rows[0];

// Check if admin is voting on an already-processed product
if (lastPresentedTicketId && firstRow.json.ticket_id !== lastPresentedTicketId) {
  return [{
    json: {
      action: 'already_reviewed',
      senderPhone: senderPhone,
      lastProcessedAction: lastProcessedAction,
      lastProcessedProductName: lastProcessedProductName,
      hasNextProduct: true,
      nextProduct: firstRow.json
    }
  }];
}

// Normal voting on the currently presented product
return [{
  json: {
    ...firstRow.json,
    replyText: replyText,
    action: action,
    senderPhone: senderPhone
  }
}];

const matchData = $('Match and Parse Reply').item.json;
const senderPhone = matchData.senderPhone || '';
const productName = matchData.Name || 'Unknown';
const ticket_id = matchData.ticket_id || '';

const staticData = $getWorkflowStaticData('global');
staticData.lastProcessedTicketId = ticket_id;
staticData.lastProcessedAction = 'approved';
staticData.lastProcessedProductName = productName;

const admins = [
  { phone: '213797841480', name: 'Admin 1' },
  { phone: '213657367547', name: 'Admin 2' },
  { phone: '213671406756', name: 'Admin 3' }
];
const excluded = ['213792102843'];

const approver = admins.find(a => senderPhone.endsWith(a.phone)) || { name: senderPhone };
const others = admins.filter(a => !senderPhone.endsWith(a.phone) && !excluded.some(ex => a.phone.endsWith(ex)));

const nextRows = $input.all();
const nextProduct = (nextRows.length > 0 && nextRows[0].json && nextRows[0].json.Name)
  ? nextRows[0].json : null;

// Track which product was just presented so late-voter detection works on subsequent votes
staticData.lastPresentedTicketId = nextProduct ? (nextProduct.ticket_id || null) : null;

let messageText;
let recipients;

if (nextProduct) {
  recipients = others;
  messageText = [
    '✅ المنتج "' + productName + '" تمت الموافقة عليه من طرف: ' + approver.name,
    '',
    'يمكنك الآن مراجعة المنتج التالي 👇',
    '',
    '📦 المنتج: ' + (nextProduct.Name || ''),
    '🔗 الرابط: ' + (nextProduct['Lien de site'] || ''),
    '📔 الصفحة: ' + (nextProduct['Lien De Page'] || ''),
    '💰 السعر: ' + (nextProduct['prix de ventes'] || ''),
    '🌍 الدولة: ' + (nextProduct.Pays || ''),
    '',
    'Confirmer?',
    '✅ OUI / OK',
    '❌ NON / ANNULER'
  ].join('\n');
} else {
  // No more products — notify ALL admins including the voter
  recipients = admins.filter(a => !excluded.some(ex => a.phone.endsWith(ex)));
  messageText = [
    '✅ المنتج "' + productName + '" تمت الموافقة عليه من طرف: ' + approver.name,
    '',
    '📭 تمت مراجعة جميع المنتجات! لا يوجد منتج آخر للمراجعة في الوقت الحالي.'
  ].join('\n');
}

if (recipients.length === 0) return [];

return recipients.map(a => ({
  json: {
    notifyPhone: a.phone,
    messageText: messageText
  }
}));

// Prepare folder name using product name only
const matchData = $('Match and Parse Reply').item.json;
const client_name = matchData.Name || $json.Name || 'Unknown';
const folderName = client_name;

return [{
  json: {
    ...matchData,
    folder_name: folderName
  }
}];

