  return (s || '').replace(/[\u200B-\u200F\u2028-\u202F\u2060-\u206F\uFEFF\u00AD]/g, '').trim().toLowerCase();
}

const triggerData = $('Classify Message').first().json;

// PRIMARY: use _replyText already extracted and cleaned by Classify Message
let replyText = triggerData._replyText || '';
let senderPhone = '';
let hasAudio = false;
let audioMediaId = '';

try {
  // Extract senderPhone and audio info from raw webhook data
  if (triggerData.entry) {
    const messages = triggerData.entry[0]?.changes?.[0]?.value?.messages;
    if (messages && messages.length > 0) {
      senderPhone = messages[0].from || '';
      if (messages[0].type === 'audio') {
        hasAudio = true;
        audioMediaId = messages[0].audio?.id || '';
        if (!replyText) replyText = 'vo oui';
      }
    }
  } else if (triggerData.messages) {
    senderPhone = triggerData.messages[0]?.from || '';
    if (triggerData.messages[0]?.type === 'audio') {
      hasAudio = true;
      audioMediaId = triggerData.messages[0].audio?.id || '';
      if (!replyText) replyText = 'vo oui';
    }
  }
} catch (e) { /* senderPhone/audio extraction failed, continue */ }

replyText = cleanText(replyText);

// Only process if reply contains 'vo' keyword or is a voice note
if (!replyText.includes('vo') && !hasAudio) {
  return [];
}

let action = 'none';
const pretWords = ['vo pret', 'vo done', 'vo prete'];
const confirmWords = ['vo oui', 'vo ok', 'vo yes', 'vo confirm'];
const cancelWords = ['vo cancel', 'vo annuler'];
const rejectWords = ['vo non', 'vo no', 'vo refuser'];

if (hasAudio || pretWords.some(w => replyText.includes(w))) {
  action = 'vo_pret';
} else if (confirmWords.some(w => replyText.includes(w))) {
  action = 'approve_vo';
} else if (cancelWords.some(w => replyText.includes(w))) {
  action = 'cancel_vo';
} else if (rejectWords.some(w => replyText.includes(w))) {
  action = 'reject_vo';
}

if (action === 'none') return [];

// Filter for pending VO rows
const rows = $input.all();
const voRows = rows.filter(r => {
  const st = (r.json.status || '').toString().trim();
  const va = (r.json.voice_over_approved || '').toString().trim().toLowerCase();
  return st === 'A_FAIRE' && va !== 'true' && va !== '1';
});

if (voRows.length === 0) {
  // Fallback: try ALL rows if status filter was too strict
  const allRows = rows.filter(r => {
    const va = (r.json.voice_over_approved || '').toString().trim().toLowerCase();
    return va !== 'true' && va !== '1';
  });
  if (allRows.length === 0) return [];
  const firstRow = allRows[0];
  const ticket_id = firstRow.json.ticket_id || 'UNKNOWN';
  const client_name = firstRow.json.Name || 'Unknown';
  const folderName = `${ticket_id}_${client_name}`;
  return [{ json: { ...firstRow.json, action, senderPhone, hasAudio, audioMediaId, replyText, folder_name_for_retry: folderName } }];
}

const firstRow = voRows[0];
const ticket_id = firstRow.json.ticket_id || 'UNKNOWN';
const client_name = firstRow.json.Name || 'Unknown';
const folderName = `${ticket_id}_${client_name}`;

return [{
  json: {
    ...firstRow.json,
    action: action,
    senderPhone: senderPhone,
    hasAudio: hasAudio,
    audioMediaId: audioMediaId,
    replyText: replyText,
    folder_name_for_retry: folderName
  }
}];

const ticket_id = $json.ticket_id || 'UNKNOWN';
const client_name = $json.Name || 'Unknown';
const folderName = `${ticket_id}_${client_name}`;
const nextStepId = (parseInt($json.step_id) || 0) + 1;

return [{
  json: {
    ...($json),
    folder_name: folderName,
    step_id_next: nextStepId
  }
}];

// Extract folder ID - prefer folder_id from sheet, then voice over link URL, fall back to search
const prevData = $('VO - Prepare Folder Name').first().json;
const searchResult = $json;

let folderId = '';
let folderName = prevData.folder_name || '';

// 1. Use folder_id column from Google Sheet
if (prevData.folder_id && prevData.folder_id.trim() !== '') {
  folderId = prevData.folder_id.trim();
}

// 2. Extract folder ID from 'voice over link' URL (column name has surrounding spaces in sheet)
const voLinkVal = prevData[' voice over link '] || prevData['voice over link'] || prevData['voice_over_link'] || '';
if (!folderId && voLinkVal) {
  const m = voLinkVal.match(/\/folders\/([a-zA-Z0-9_-]+)/);
  if (m) folderId = m[1];
}

// 3. Fall back to Google Drive name search result
if (!folderId && searchResult.files && searchResult.files.length > 0) {
  folderId = searchResult.files[0].id;
  folderName = searchResult.files[0].name;
}

return [{
  json: {
    ...prevData,
    folderId: folderId,
    folderName: folderName,
    folderFound: folderId !== ''
  }
}];

// VO - Extract File v3 (robust retry via staticData + audio filtering)
const prevData = $('VO - Extract Folder').first().json;
const searchResult = $json;

// --- Use workflow static data for reliable retry counting ---
// (persists across loop iterations even when HTTP Request replaces data)
const staticData = $getWorkflowStaticData('global');
const retryKey = 'vo_file_retry_' + (prevData.ticket_id || prevData.folderId || 'default');
const currentRetry = staticData[retryKey] || 0;
const maxRetries = 5;

let fileId = '';
let fileName = '';
let fileMimeType = '';
let fileLink = '';
let filesList = [];

// --- Handle ALL possible response formats from HTTP Request ---
if (searchResult.files && Array.isArray(searchResult.files)) {
  filesList = searchResult.files;
} else if (searchResult.data && searchResult.data.files && Array.isArray(searchResult.data.files)) {
  filesList = searchResult.data.files;
} else if (Array.isArray(searchResult)) {
  filesList = searchResult;
} else if (searchResult.items && Array.isArray(searchResult.items)) {
  filesList = searchResult.items;
}

// --- Filter for audio files only (mimeType starts with 'audio/') ---
const audioFiles = filesList.filter(f => {
  const mime = (f.mimeType || '').toLowerCase();
  return mime.startsWith('audio/');
});

// Prefer audio files; fall back to all files if none match
const targetFiles = audioFiles.length > 0 ? audioFiles : filesList;

if (targetFiles.length > 0) {
  const chosen = targetFiles[0];
  fileId = chosen.id || '';
  fileName = chosen.name || '';
  fileMimeType = chosen.mimeType || '';
  fileLink = chosen.webViewLink || '';
}

// --- Retry logic using staticData ---
const shouldRetry = fileId === '' && currentRetry < maxRetries;

if (shouldRetry) {
  // Increment retry counter for next iteration
  staticData[retryKey] = currentRetry + 1;
} else {
  // Reset counter: either file found or max retries exhausted
  delete staticData[retryKey];
}

return [{
  json: {
    ...prevData,
    id: fileId,
    fileName: fileName,
    fileMimeType: fileMimeType,
    fileLink: fileLink,
    fileFound: fileId !== '',
    isAudioFile: audioFiles.length > 0,
    _retryCount: currentRetry,
    _shouldRetry: shouldRetry,
    _debug_totalFiles: filesList.length,
    _debug_audioFiles: audioFiles.length,
    _debug_rawKeys: Object.keys(searchResult || {}).join(','),
    _debug_folderId: prevData.folderId || 'NO_FOLDER_ID'
  }
}];

