    }
  }
  if (!replyText && triggerData.messages) {
    if (triggerData.messages[0].type === 'audio') {
      replyText = 'vo oui';
    } else {
      replyText = triggerData.messages[0].text?.body || '';
    }
  }
  if (!replyText && triggerData.text) {
    replyText = typeof triggerData.text === 'string' ? triggerData.text : (triggerData.text?.body || '');
  }
  if (!replyText && triggerData.body) {
    replyText = typeof triggerData.body === 'string' ? triggerData.body : '';
  }
} catch (e) {
  replyText = '';
}

replyText = cleanText(replyText);

let route = 'general';
if (replyText.startsWith('vo ') || replyText === 'vo') {
  route = 'vo';
} else if (replyText.startsWith('mt ') || replyText === 'mt') {
  route = 'mt';
}
return [{ json: { ...triggerData, _route: route, _replyText: replyText } }];

