const data = $json;
const staticData = $getWorkflowStaticData('global');
const action = data.action;
const senderPhone = data.senderPhone || '';
const lastProcessedAction = staticData.lastProcessedAction || data.lastProcessedAction || '';
const lastProcessedProductName = staticData.lastProcessedProductName || data.lastProcessedProductName || 'منتج سابق';
const hasNextProduct = data.hasNextProduct === true;
const nextProduct = data.nextProduct || null;

if (!senderPhone) return [];

// Update lastPresentedTicketId so future votes from this admin target the next product
if (hasNextProduct && nextProduct && nextProduct.ticket_id) {
  staticData.lastPresentedTicketId = nextProduct.ticket_id;
}

const actionText = lastProcessedAction === 'approved' ? 'تم قبوله ✅'
  : lastProcessedAction === 'rejected' ? 'تم رفضه ❌'
  : 'تمت مراجعته';

let message = '';
if (action === 'no_pending') {
  if (lastProcessedProductName && lastProcessedProductName !== 'منتج سابق') {
    message = `⚡ المنتج "${lastProcessedProductName}" ${actionText} من طرف أدمين آخر.\n\n📭 فضيتو المنتجات! لا يوجد منتج آخر للمراجعة في الوقت الحالي.`;
  } else {
    message = `📭 فضيتو المنتجات! لا يوجد منتج للمراجعة في الوقت الحالي.`;
  }
} else if (action === 'already_reviewed') {
  message = `⚡ المنتج "${lastProcessedProductName}" ${actionText} من طرف أدمين آخر.\n\nيمكنك الانتقال لمراجعة المنتج الموالي:`;
  if (hasNextProduct && nextProduct) {
    message += `\n\n📦 المنتج الموالي:\n- الاسم: ${nextProduct.Name || 'غير معروف'}\n- الرابط: ${nextProduct['Lien de site'] || ''}\n- الصفحة: ${nextProduct['Lien De Page'] || ''}\n- السعر: ${nextProduct['prix de ventes'] || ''}\n- الدولة: ${nextProduct.Pays || ''}\n\nConfirmer?\n✅ OUI / OK\n❌ NON / ANNULER`;
  } else {
    message += `\n\n📭 لا يوجد منتج موالي للمراجعة.`;
  }
}

return [{ json: { message, senderPhone } }];

const matchData = $('Match and Parse Reply').item.json;
const senderPhone = matchData.senderPhone || '';
const productName = matchData.Name || 'Unknown';
const ticket_id = matchData.ticket_id || '';

const staticData = $getWorkflowStaticData('global');
staticData.lastProcessedTicketId = ticket_id;
staticData.lastProcessedAction = 'rejected';
staticData.lastProcessedProductName = productName;

const admins = [
  { phone: '213797841480', name: 'Admin 1' },
  { phone: '213657367547', name: 'Admin 2' },
  { phone: '213671406756', name: 'Admin 3' }
];
const excluded = ['213792102843'];

const rejector = admins.find(a => senderPhone.endsWith(a.phone)) || { name: senderPhone };
const others = admins.filter(a => !senderPhone.endsWith(a.phone) && !excluded.some(ex => a.phone.endsWith(ex)));

const nextRows = $input.all();
const nextProduct = (nextRows.length > 0 && nextRows[0].json && nextRows[0].json.Name)
  ? nextRows[0].json : null;

// Track which product was just presented so late-voter detection works on subsequent votes
staticData.lastPresentedTicketId = nextProduct ? (nextProduct.ticket_id || null) : null;

let messageText;
let recipients;

if (nextProduct) {
  recipients = others;
  messageText = [
    '❌ المنتج "' + productName + '" تم رفضه من طرف: ' + rejector.name,
    '',
    'يمكنك الآن مراجعة المنتج التالي 👇',
    '',
    '📦 المنتج: ' + (nextProduct.Name || ''),
    '🔗 الرابط: ' + (nextProduct['Lien de site'] || ''),
    '📔 الصفحة: ' + (nextProduct['Lien De Page'] || ''),
    '💰 السعر: ' + (nextProduct['prix de ventes'] || ''),
    '🌍 الدولة: ' + (nextProduct.Pays || ''),
    '',
    'Confirmer?',
    '✅ OUI / OK',
    '❌ NON / ANNULER'
  ].join('\n');
} else {
  // No more products — notify ALL admins including the voter
  recipients = admins.filter(a => !excluded.some(ex => a.phone.endsWith(ex)));
  messageText = [
    '❌ المنتج "' + productName + '" تم رفضه من طرف: ' + rejector.name,
    '',
    '📭 تمت مراجعة جميع المنتجات! لا يوجد منتج آخر للمراجعة في الوقت الحالي.'
  ].join('\n');
}

if (recipients.length === 0) return [];

return recipients.map(a => ({
  json: {
    notifyPhone: a.phone,
    messageText: messageText
  }
}));
